method.example:
// Full resource: {"name": "Alice", "email": "a@example.com", "role": "user"}
// PATCH to change just the role:
PATCH /users/42
{"role": "admin"}
// email and name are untouched

// PATCH to clear a field:
PATCH /users/42
{"middleName": null}

error-response.format:
{
  "error": {
    "code": "InvalidPasswordFormat",
    "message": "The password does not meet the minimum length requirement.",
    "target": "password",
    "details": [
      {
        "code": "PasswordTooShort",
        "message": "Password must be at least 8 characters.",
        "target": "password"
      }
    ],
    "innererror": {
      "code": "PasswordTooShort",
      "minLength": 8
    }
  }
}

long-running-operations.polling-pattern:
// 1. Start the operation
POST /import-jobs
HTTP/1.1 202 Accepted
operation-location: https://api.example.com/operations/abc123?api-version=2024-03-17

// 2. Poll until terminal status
GET https://api.example.com/operations/abc123?api-version=2024-03-17
HTTP/1.1 200 OK
retry-after: 5
{"id":"abc123","status":"Running","percentComplete":60}

// 3. Terminal — read result
{"id":"abc123","status":"Succeeded","result":{"importedCount":1500}}
